import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { BarChart3 } from 'lucide-react';
import fareDistribution from '@/data/fare_distribution.json';
import type { FareDistributionBin } from '@/types/charts';
import { axisTick, compactNumber, tooltipStyle } from './chartTheme';

/**
 * Fare distribution histogram — simple `pd.cut` + `value_counts` over fare_amount,
 * generated by scripts/generate_chart_data.py (same pattern as the notebook's
 * value_counts cells).
 */
export function FareDistributionChart() {
  const data = fareDistribution as FareDistributionBin[];

  return (
    <Card className="rounded-lg border">
      <CardHeader className="flex-row items-center gap-2 space-y-0 pb-3">
        <BarChart3 className="h-5 w-5 text-muted-foreground" />
        <div>
          <CardTitle className="text-lg font-semibold">Fare Distribution</CardTitle>
          <CardDescription className="text-sm">
            How fares cluster across the dataset
          </CardDescription>
        </div>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={240}>
          <BarChart data={data} margin={{ top: 10, right: 10, left: 10, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} />
            <XAxis dataKey="range" tick={axisTick} axisLine={false} tickLine={false} interval={0} />
            <YAxis
              tick={axisTick}
              axisLine={false}
              tickLine={false}
              tickFormatter={compactNumber}
            />
            <Tooltip
              cursor={{ fill: 'var(--accent)' }}
              contentStyle={tooltipStyle}
              formatter={(value) => [
                typeof value === 'number' ? value.toLocaleString() : String(value),
                'Trips',
              ]}
              labelFormatter={(label) => `Fare ${String(label)}`}
            />
            <Bar dataKey="count" fill="var(--chart-1)" radius={[4, 4, 0, 0]} maxBarSize={48} />
          </BarChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
}
